use std::sync::Arc;
use launcher_core::{auth, launch, manifest, LauncherPaths};
use serde::{Deserialize, Serialize};
use specta::Type;
use tauri::{AppHandle, Emitter};

mod input;

#[derive(Clone)]
struct AppState { client: Arc<reqwest::Client>, paths: Arc<LauncherPaths> }
impl AppState { fn new() -> Self { let client = reqwest::Client::builder().user_agent("kidomc/0.1.0").timeout(std::time::Duration::from_secs(30)).build().expect("http client"); Self { client: Arc::new(client), paths: Arc::new(launcher_core::default_paths()) } } }
fn undashed_uuid(id: &str) -> String { if id.len() == 32 { format!("{}-{}-{}-{}-{}", &id[..8], &id[8..12], &id[12..16], &id[16..20], &id[20..]) } else { id.to_string() } }

#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct VersionEntry { id: String, #[serde(rename = "type")] version_type: String, url: String }
impl From<&manifest::VersionEntry> for VersionEntry { fn from(v: &manifest::VersionEntry) -> Self { Self { id: v.id.clone(), version_type: v.version_type.clone(), url: v.url.clone() } } }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct DeviceCodeInfo { user_code: String, verification_uri: String, message: String }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct LaunchProgress { phase: String, percent: u8, message: String }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct FabricLoaderVersion { version: String, stable: bool }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct CreateInstanceRequest { name: String, minecraft_version: String, memory_mb: u32, loader: String, fabric_loader_version: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct UpdateInstanceRequest { name: Option<String>, minecraft_version: Option<String>, memory_mb: Option<u32>, loader: Option<String>, fabric_loader_version: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct MrPackPreview { name: String, version_id: String, minecraft_version: String, loader: String, loader_version: Option<String>, mod_count: u32, summary: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct CfModInfo { id: u32, name: String, summary: String, author: String, download_count: f64, slug: String, logo_url: Option<String>, allow_mod_distribution: Option<bool> }
#[derive(Debug, Clone, Serialize, Deserialize, Type)] struct CfModFile { id: u32, mod_id: u32, display_name: String, file_name: String, game_versions: Vec<String>, is_available: bool, file_length: f64 }

#[tauri::command] #[specta::specta] async fn list_versions(state: tauri::State<'_, AppState>) -> Result<Vec<VersionEntry>, String> { let v2 = manifest::fetch_version_manifest_v2(&state.client, &state.paths.meta_dir().join("manifests")).await.map_err(|e| e.to_string())?; Ok(v2.versions.iter().filter(|v| v.version_type == "release").map(VersionEntry::from).collect()) }
#[tauri::command] #[specta::specta] async fn list_fabric_loaders(state: tauri::State<'_, AppState>, mc_version: String) -> Result<Vec<FabricLoaderVersion>, String> { launcher_core::loaders::fabric::get_loader_versions_for_mc(&state.client, &mc_version).await.map_err(|e| e.to_string()).map(|v| v.into_iter().map(|lv| FabricLoaderVersion { version: lv.version, stable: lv.stable }).collect()) }
#[tauri::command] #[specta::specta] async fn list_accounts(_state: tauri::State<'_, AppState>) -> Result<Vec<auth::MicrosoftAccount>, String> { auth::store::load_accounts().await.map_err(|e| e.to_string()).map(|s| s.accounts) }
#[tauri::command] #[specta::specta] async fn begin_msa_login(app: AppHandle, state: tauri::State<'_, AppState>) -> Result<DeviceCodeInfo, String> { let cid = auth::client_id(); let device = auth::msa::request_device_code(&state.client, &cid).await.map_err(|e| e.to_string())?; let device_code = device.device_code.clone(); let interval = device.interval; let client = state.client.clone(); let cid_c = cid.clone(); tauri::async_runtime::spawn(async move { let token = match auth::msa::poll_for_token(&client, &cid_c, &device_code, interval).await { Ok(t) => t, Err(e) => { let _ = app.emit("login-failed", e.to_string()); return; } }; let refresh_token = match token.refresh_token.clone() { Some(rt) => rt, None => return }; let xbox = match auth::xbox::full_authenticate(&client, &token.access_token).await { Ok(t) => t, Err(e) => { let _ = app.emit("login-failed", e.to_string()); return; } }; let (mc_token, expires_in) = match auth::minecraft::authenticate_with_xbox(&client, &xbox.uhs, &xbox.xsts_token).await { Ok(t) => t, Err(e) => { let _ = app.emit("login-failed", e.to_string()); return; } }; if let Err(e) = auth::minecraft::check_entitlements(&client, &mc_token).await { let _ = app.emit("login-failed", e.to_string()); return; } let profile = match auth::minecraft::get_profile(&client, &mc_token).await { Ok(p) => p, Err(e) => { let _ = app.emit("login-failed", e.to_string()); return; } }; let expires_at = (chrono::Utc::now().timestamp() + expires_in as i64) as f64; let account = auth::MicrosoftAccount { id: profile.id.clone(), username: profile.name.clone(), uuid: undashed_uuid(&profile.id), access_token: mc_token, expires_at, refresh_token, xuid: xbox.uhs.clone(), is_default: true }; if let Err(e) = auth::store::save_account(&account).await { let _ = app.emit("login-failed", e.to_string()); return; } let _ = app.emit("login-completed", account); }); Ok(DeviceCodeInfo { user_code: device.user_code, verification_uri: device.verification_uri, message: device.message }) }

#[tauri::command] #[specta::specta] async fn launch_vanilla(app: AppHandle, version: String, memory_mb: u32, state: tauri::State<'_, AppState>) -> Result<(), String> { let client = state.client.clone(); let paths = state.paths.clone(); tauri::async_runtime::spawn(async move { if let Err(e) = do_launch(app.clone(), client, paths, version, memory_mb).await { let _ = app.emit("launch-failed", e.to_string()); } }); Ok(()) }
async fn do_launch(app: AppHandle, client: Arc<reqwest::Client>, paths: Arc<LauncherPaths>, version: String, memory_mb: u32) -> Result<(), String> { let account = auth::get_login_account(&client).await.map_err(|e| e.to_string())?.as_ref().cloned(); let (progress_tx, mut progress_rx) = tokio::sync::mpsc::unbounded_channel(); let default_game_dir = paths.instances_dir().join(&version); let launch_future = launch::launch_vanilla(&client, &paths, &version, memory_mb, account.as_ref(), None, &default_game_dir, progress_tx); tokio::spawn({ let app = app.clone(); async move { while let Some(p) = progress_rx.recv().await { let _ = app.emit("launch-progress", LaunchProgress { phase: p.label.clone(), percent: p.percent, message: format!("{} {}%", p.label, p.percent) }); } } }); let mut handle = launch_future.await.map_err(|e| e.to_string())?; let mut log_rx = handle.take_log_receiver(); while let Some(log) = log_rx.recv().await { let _ = app.emit("launch-log", log); } match handle.wait().await { Ok(code) => { let _ = app.emit("launch-exited", code); } Err(e) => { let _ = app.emit("launch-failed", e.to_string()); } } Ok(()) }

#[tauri::command] #[specta::specta] async fn launch_instance(app: AppHandle, id: String, state: tauri::State<'_, AppState>) -> Result<(), String> { let client = state.client.clone(); let paths = state.paths.clone(); tauri::async_runtime::spawn(async move { let _ = app.emit(format!("launch:{id}:started").as_str(), &id); let _ = app.emit("launch-started", &id); if let Err(e) = do_launch_instance(app.clone(), client, paths, id).await { let _ = app.emit("launch-failed", e.to_string()); } }); Ok(()) }
async fn do_launch_instance(app: AppHandle, client: Arc<reqwest::Client>, paths: Arc<LauncherPaths>, instance_id: String) -> Result<(), String> { let detail = launcher_core::instance::get_instance(&paths, &instance_id).await.map_err(|e| e.to_string())?; let account = auth::get_login_account(&client).await.map_err(|e| e.to_string())?.as_ref().cloned(); let (progress_tx, mut progress_rx) = tokio::sync::mpsc::unbounded_channel(); let version = detail.summary.minecraft_version.clone(); let memory = detail.memory_mb; let fabric_version = match &detail.summary.loader { launcher_core::instance::LoaderInfo::Fabric { loader_version } => Some(loader_version.as_str()), _ => None }; let game_dir = detail.path.clone(); let launch_future = launch::launch_vanilla(&client, &paths, &version, memory, account.as_ref(), fabric_version, &game_dir, progress_tx); let iid = instance_id.clone(); tokio::spawn({ let app = app.clone(); let iid = iid.clone(); async move { while let Some(p) = progress_rx.recv().await { let _ = app.emit(format!("launch:{iid}:progress").as_str(), LaunchProgress { phase: p.label.clone(), percent: p.percent, message: format!("{} {}%", p.label, p.percent) }); } } }); let mut handle = launch_future.await.map_err(|e| e.to_string())?; let mut log_rx = handle.take_log_receiver(); while let Some(log) = log_rx.recv().await { let _ = app.emit(format!("launch:{iid}:log").as_str(), log); } launcher_core::instance::record_launch(&paths, &instance_id).await.ok(); match handle.wait().await { Ok(code) => { let _ = app.emit(format!("launch:{iid}:exited").as_str(), code); } Err(e) => { let _ = app.emit(format!("launch:{iid}:failed").as_str(), e.to_string()); } } Ok(()) }

#[tauri::command] #[specta::specta] async fn search_mods(state: tauri::State<'_, AppState>, query: String, loader: Option<String>, game_version: Option<String>) -> Result<Vec<launcher_core::modrinth::SearchHit>, String> { let filters = launcher_core::modrinth::SearchFilters { query, loader, game_version, limit: 30, offset: 0 }; launcher_core::modrinth::search(&state.client, &filters).await.map_err(|e| e.to_string()).map(|r| r.hits) }
#[tauri::command] #[specta::specta] async fn get_mod_project(state: tauri::State<'_, AppState>, project_id: String) -> Result<launcher_core::modrinth::Project, String> { launcher_core::modrinth::get_project(&state.client, &project_id).await.map_err(|e| e.to_string()) }
#[tauri::command] #[specta::specta] async fn get_mod_versions(state: tauri::State<'_, AppState>, project_id: String, loader: Option<String>, game_version: Option<String>) -> Result<Vec<launcher_core::modrinth::Version>, String> { launcher_core::modrinth::list_versions(&state.client, &project_id, loader.as_deref(), game_version.as_deref()).await.map_err(|e| e.to_string()) }
#[tauri::command] #[specta::specta] async fn install_mod(state: tauri::State<'_, AppState>, instance_id: String, version_id: String) -> Result<(), String> { let version = launcher_core::modrinth::get_version(&state.client, &version_id).await.map_err(|e| e.to_string())?; let file = launcher_core::modrinth::pick_primary_file(&version).ok_or_else(|| "no file found".to_string())?; let mods_dir = launcher_core::instance::instance_dir(&state.paths, &instance_id).join(".minecraft").join("mods"); tokio::fs::create_dir_all(&mods_dir).await.map_err(|e| e.to_string())?; let dest = mods_dir.join(&file.filename); launcher_core::download::Downloader::new(state.client.as_ref().clone()).download(&file.url, &dest, Some(&file.hashes.sha1)).await.map_err(|e| e.to_string())?; let mut detail = launcher_core::instance::get_instance(&state.paths, &instance_id).await.map_err(|e| e.to_string())?; if detail.mods.iter().any(|m| m.filename == file.filename) { return Err("mod already installed".to_string()); } detail.summary.mod_count += 1; let project = launcher_core::modrinth::get_project(&state.client, &version.project_id).await.ok(); detail.mods.push(launcher_core::instance::InstalledMod { filename: file.filename.clone(), source: launcher_core::instance::ModSource::Modrinth { project_id: version.project_id.clone(), version_id }, mod_id: Some(version.project_id.clone()), name: project.as_ref().map(|p| p.title.clone()), description: project.as_ref().map(|p| p.description.clone()), icon_url: project.as_ref().and_then(|p| p.icon_url.clone()), version: Some(version.version_number.clone()), sha1: Some(file.hashes.sha1.clone()), disabled: false }); let json_path = launcher_core::instance::instance_json(&state.paths, &instance_id); let json = serde_json::to_string_pretty(&detail).map_err(|e| e.to_string())?; let tmp = json_path.with_extension("json.tmp"); tokio::fs::write(&tmp, &json).await.map_err(|e| e.to_string())?; tokio::fs::rename(&tmp, &json_path).await.map_err(|e| e.to_string())?; Ok(()) }
#[tauri::command] #[specta::specta] async fn toggle_mod(state: tauri::State<'_, AppState>, instance_id: String, filename: String) -> Result<(), String> { let mut detail = launcher_core::instance::get_instance(&state.paths, &instance_id).await.map_err(|e| e.to_string())?; let mod_entry = detail.mods.iter_mut().find(|m| m.filename == filename).ok_or_else(|| "mod not found".to_string())?; mod_entry.disabled = !mod_entry.disabled; let mods_dir = launcher_core::instance::instance_dir(&state.paths, &instance_id).join(".minecraft").join("mods"); if mod_entry.disabled { let from = mods_dir.join(&filename); let to = mods_dir.join(format!("{}.disabled", filename)); if from.exists() { tokio::fs::rename(&from, &to).await.map_err(|e| e.to_string())?; } } else { let from = mods_dir.join(format!("{}.disabled", filename)); let to = mods_dir.join(&filename); if from.exists() { tokio::fs::rename(&from, &to).await.map_err(|e| e.to_string())?; } } let json_path = launcher_core::instance::instance_json(&state.paths, &instance_id); let json = serde_json::to_string_pretty(&detail).map_err(|e| e.to_string())?; let tmp = json_path.with_extension("json.tmp"); tokio::fs::write(&tmp, &json).await.map_err(|e| e.to_string())?; tokio::fs::rename(&tmp, &json_path).await.map_err(|e| e.to_string())?; Ok(()) }
#[tauri::command] #[specta::specta] async fn delete_mod(state: tauri::State<'_, AppState>, instance_id: String, filename: String) -> Result<(), String> { let mut detail = launcher_core::instance::get_instance(&state.paths, &instance_id).await.map_err(|e| e.to_string())?; let idx = detail.mods.iter().position(|m| m.filename == filename).ok_or_else(|| "mod not found".to_string())?; let mod_entry = &detail.mods[idx]; let mods_dir = launcher_core::instance::instance_dir(&state.paths, &instance_id).join(".minecraft").join("mods"); let jar_path = if mod_entry.disabled { mods_dir.join(format!("{}.disabled", filename)) } else { mods_dir.join(&filename) }; tokio::fs::remove_file(&jar_path).await.ok(); detail.mods.remove(idx); detail.summary.mod_count = detail.summary.mod_count.saturating_sub(1); let json_path = launcher_core::instance::instance_json(&state.paths, &instance_id); let json = serde_json::to_string_pretty(&detail).map_err(|e| e.to_string())?; let tmp = json_path.with_extension("json.tmp"); tokio::fs::write(&tmp, &json).await.map_err(|e| e.to_string())?; tokio::fs::rename(&tmp, &json_path).await.map_err(|e| e.to_string())?; Ok(()) }

#[tauri::command] #[specta::specta] async fn list_instances(state: tauri::State<'_, AppState>) -> Result<Vec<launcher_core::instance::InstanceSummary>, String> { launcher_core::instance::list_instances(&state.paths).await.map_err(|e| e.to_string()) }
#[tauri::command] #[specta::specta] async fn get_instance(state: tauri::State<'_, AppState>, id: String) -> Result<launcher_core::instance::InstanceDetail, String> { launcher_core::instance::get_instance(&state.paths, &id).await.map_err(|e| e.to_string()) }
#[tauri::command] #[specta::specta] async fn create_instance(state: tauri::State<'_, AppState>, request: CreateInstanceRequest) -> Result<String, String> { let loader = match request.loader.as_str() { "fabric" => launcher_core::instance::LoaderInfo::Fabric { loader_version: request.fabric_loader_version.unwrap_or_else(|| "0.16.0".to_string()) }, _ => launcher_core::instance::LoaderInfo::Vanilla }; let spec = launcher_core::instance::NewInstanceSpec { name: request.name, minecraft_version: request.minecraft_version, loader, memory_mb: request.memory_mb }; launcher_core::instance::create_instance(&state.paths, &spec).await.map_err(|e| e.to_string()) }
#[tauri::command] #[specta::specta] async fn delete_instance(state: tauri::State<'_, AppState>, id: String) -> Result<(), String> { launcher_core::instance::delete_instance(&state.paths, &id).await.map_err(|e| e.to_string()) }
#[tauri::command] #[specta::specta] async fn update_instance(state: tauri::State<'_, AppState>, id: String, request: UpdateInstanceRequest) -> Result<(), String> { let mut detail = launcher_core::instance::get_instance(&state.paths, &id).await.map_err(|e| e.to_string())?; if let Some(name) = request.name { detail.summary.name = name; } if let Some(ver) = request.minecraft_version { detail.summary.minecraft_version = ver; } if let Some(mem) = request.memory_mb { detail.memory_mb = mem; } if let Some(ref loader_str) = request.loader { detail.summary.loader = match loader_str.as_str() { "fabric" => launcher_core::instance::LoaderInfo::Fabric { loader_version: request.fabric_loader_version.unwrap_or_else(|| "0.16.0".to_string()) }, _ => launcher_core::instance::LoaderInfo::Vanilla }; } else if let Some(ref fv) = request.fabric_loader_version { if let launcher_core::instance::LoaderInfo::Fabric { ref mut loader_version } = detail.summary.loader { *loader_version = fv.clone(); } } let json_path = launcher_core::instance::instance_json(&state.paths, &id); let json = serde_json::to_string_pretty(&detail).map_err(|e| e.to_string())?; let tmp = json_path.with_extension("json.tmp"); tokio::fs::write(&tmp, &json).await.map_err(|e| e.to_string())?; tokio::fs::rename(&tmp, &json_path).await.map_err(|e| e.to_string())?; Ok(()) }
#[tauri::command] #[specta::specta] async fn quit_app(app: AppHandle) -> Result<(), String> { app.exit(0); Ok(()) }
#[tauri::command] #[specta::specta] async fn get_java_version(state: tauri::State<'_, AppState>, mc_version: String) -> Result<Option<launcher_core::manifest::JavaVersion>, String> { let v2 = launcher_core::manifest::fetch_version_manifest_v2(&state.client, &state.paths.meta_dir().join("manifests")).await.map_err(|e| e.to_string())?; let entry = launcher_core::manifest::find_version(&v2, &mc_version).map_err(|e| e.to_string())?; let manifest = launcher_core::manifest::fetch_version_manifest(&state.client, entry, &state.paths.meta_dir().join("versions")).await.map_err(|e| e.to_string())?; Ok(manifest.java_version) }

#[tauri::command] #[specta::specta] async fn preview_mrpack(state: tauri::State<'_, AppState>, path: String) -> Result<MrPackPreview, String> { let (index, _) = launcher_core::modpack::mrpack::read_mrpack(std::path::Path::new(&path)).await.map_err(|e| e.to_string())?; let mc_version = index.dependencies.get("minecraft").cloned().unwrap_or_default(); let (loader, loader_version) = if let Some(fv) = index.dependencies.get("fabric-loader") { ("fabric", Some(fv.clone())) } else { ("vanilla", None) }; Ok(MrPackPreview { name: index.name, version_id: index.version_id, minecraft_version: mc_version, loader: loader.to_string(), loader_version, mod_count: index.files.len() as u32, summary: index.summary }) }
#[tauri::command] #[specta::specta] async fn import_mrpack(app: AppHandle, state: tauri::State<'_, AppState>, path: String) -> Result<String, String> { let paths = state.paths.clone(); let client = state.client.clone(); let app_handle = app.clone(); tauri::async_runtime::spawn(async move { let r = do_import_mrpack(&client, &paths, &path, &app_handle).await; match r { Ok(id) => { let _ = app_handle.emit("import-completed", id); } Err(e) => { let _ = app_handle.emit("import-failed", e.to_string()); } } }); Ok("importing".to_string()) }
async fn do_import_mrpack(client: &reqwest::Client, paths: &LauncherPaths, mrpack_path: &str, app: &AppHandle) -> Result<String, String> { use launcher_core::modpack::mrpack; let (index, data) = mrpack::read_mrpack(std::path::Path::new(mrpack_path)).await.map_err(|e| e.to_string())?; let mc_version = index.dependencies.get("minecraft").cloned().unwrap_or_default(); let loader = if index.dependencies.contains_key("fabric-loader") { launcher_core::instance::LoaderInfo::Fabric { loader_version: index.dependencies.get("fabric-loader").cloned().unwrap_or_else(|| "0.16.0".to_string()) } } else { launcher_core::instance::LoaderInfo::Vanilla }; let spec = launcher_core::instance::NewInstanceSpec { name: index.name.clone(), minecraft_version: mc_version, loader, memory_mb: 4096 }; let instance_id = launcher_core::instance::create_instance(paths, &spec).await.map_err(|e| e.to_string())?; let minecraft_dir = launcher_core::instance::instance_dir(paths, &instance_id).join(".minecraft"); let mods_dir = minecraft_dir.join("mods"); tokio::fs::create_dir_all(&mods_dir).await.map_err(|e| e.to_string())?; let total = index.files.len(); for (i, file) in index.files.iter().enumerate() { if let Some(ref env) = file.env { if env.client == "unsupported" { continue; } } let url = file.downloads.first().ok_or_else(|| format!("no download url for {}", file.path))?; mrpack::validate_download_url(url).map_err(|e| e.to_string())?; let dest = minecraft_dir.join(&file.path); if let Some(parent) = dest.parent() { tokio::fs::create_dir_all(parent).await.map_err(|e| e.to_string())?; } let downloader = launcher_core::download::Downloader::new(client.clone()); downloader.download(url, &dest, file.hashes.sha1.as_deref()).await.map_err(|e| e.to_string())?; let _ = app.emit("import-progress", serde_json::json!({"phase": "downloading", "current": i + 1, "total": total})); } let _ = app.emit("import-progress", serde_json::json!({"phase": "overrides"})); mrpack::extract_overrides(&data, &minecraft_dir, "overrides/").await.map_err(|e| e.to_string())?; mrpack::extract_overrides(&data, &minecraft_dir, "client-overrides/").await.ok(); let mut detail = launcher_core::instance::get_instance(paths, &instance_id).await.map_err(|e| e.to_string())?; let mut installed = Vec::new(); for file in &index.files { if file.path.starts_with("mods/") { let filename = std::path::Path::new(&file.path).file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(); installed.push(launcher_core::instance::InstalledMod { filename, source: launcher_core::instance::ModSource::Modrinth { project_id: String::new(), version_id: String::new() }, mod_id: None, name: None, description: None, icon_url: None, version: None, sha1: file.hashes.sha1.clone(), disabled: false }); } } detail.mods = installed; detail.summary.mod_count = detail.mods.len() as u32; let json_path = launcher_core::instance::instance_json(paths, &instance_id); let json = serde_json::to_string_pretty(&detail).map_err(|e| e.to_string())?; let tmp = json_path.with_extension("json.tmp"); tokio::fs::write(&tmp, &json).await.map_err(|e| e.to_string())?; tokio::fs::rename(&tmp, &json_path).await.map_err(|e| e.to_string())?; Ok(instance_id) }

#[tauri::command] #[specta::specta] async fn search_cf_mods(state: tauri::State<'_, AppState>, query: String, loader: String, game_version: Option<String>) -> Result<Vec<CfModInfo>, String> { let lt = match loader.as_str() { "fabric" => 4, _ => 0 }; let resp = launcher_core::curseforge::search_mods(&state.client, &query, lt, game_version.as_deref(), 0).await.map_err(|e| e.to_string())?; Ok(resp.data.into_iter().map(|m| CfModInfo { id: m.id, name: m.name, summary: m.summary, author: m.authors.first().map(|a| a.name.clone()).unwrap_or_default(), download_count: m.download_count, slug: m.slug, logo_url: m.logo.as_ref().map(|l| l.thumbnail_url.clone()), allow_mod_distribution: m.allow_mod_distribution }).collect()) }
#[tauri::command] #[specta::specta] async fn get_cf_files(state: tauri::State<'_, AppState>, mod_id: u32) -> Result<Vec<CfModFile>, String> { let files = launcher_core::curseforge::get_files(&state.client, mod_id).await.map_err(|e| e.to_string())?; Ok(files.into_iter().map(|f| CfModFile { id: f.id, mod_id: f.mod_id, display_name: f.display_name, file_name: f.file_name, game_versions: f.game_versions, is_available: f.is_available, file_length: f.file_length as f64 }).collect()) }
#[tauri::command] #[specta::specta] async fn install_cf_mod(state: tauri::State<'_, AppState>, instance_id: String, mod_id: u32, file_id: u32) -> Result<(), String> { let mod_info = launcher_core::curseforge::get_mod(&state.client, mod_id).await.map_err(|e| e.to_string())?; if mod_info.allow_mod_distribution == Some(false) { return Err("author disabled third-party downloads".to_string()); } let dl_url = launcher_core::curseforge::get_download_url(&state.client, mod_id, file_id).await.map_err(|e| e.to_string())?; let files = launcher_core::curseforge::get_files(&state.client, mod_id).await.map_err(|e| e.to_string())?; let file = files.iter().find(|f| f.id == file_id).ok_or_else(|| "file not found".to_string())?; let mods_dir = launcher_core::instance::instance_dir(&state.paths, &instance_id).join(".minecraft").join("mods"); tokio::fs::create_dir_all(&mods_dir).await.map_err(|e| e.to_string())?; let dest = mods_dir.join(&file.file_name); launcher_core::download::Downloader::new(state.client.as_ref().clone()).download(&dl_url, &dest, file.hashes.first().map(|h| h.value.as_str())).await.map_err(|e| e.to_string())?; let mut detail = launcher_core::instance::get_instance(&state.paths, &instance_id).await.map_err(|e| e.to_string())?; if detail.mods.iter().any(|m| m.filename == file.file_name) { return Err("mod already installed".to_string()); } detail.summary.mod_count += 1; detail.mods.push(launcher_core::instance::InstalledMod { filename: file.file_name.clone(), source: launcher_core::instance::ModSource::CurseForge { project_id: mod_id.to_string(), file_id: file_id.to_string() }, mod_id: Some(mod_id.to_string()), name: Some(mod_info.name.clone()), description: Some(mod_info.summary.clone()), icon_url: mod_info.logo.as_ref().map(|l| l.thumbnail_url.clone()), version: Some(file.display_name.clone()), sha1: file.hashes.first().map(|h| h.value.clone()), disabled: false }); let json_path = launcher_core::instance::instance_json(&state.paths, &instance_id); let json = serde_json::to_string_pretty(&detail).map_err(|e| e.to_string())?; let tmp = json_path.with_extension("json.tmp"); tokio::fs::write(&tmp, &json).await.map_err(|e| e.to_string())?; tokio::fs::rename(&tmp, &json_path).await.map_err(|e| e.to_string())?; Ok(()) }

#[tauri::command] #[specta::specta] async fn import_cf_zip(app: AppHandle, state: tauri::State<'_, AppState>, path: String) -> Result<String, String> { let paths = state.paths.clone(); let client = state.client.clone(); let app_handle = app.clone(); tauri::async_runtime::spawn(async move { let r = do_import_cf_zip(&client, &paths, &path, &app_handle).await; match r { Ok(id) => { let _ = app_handle.emit("import-completed", id); } Err(e) => { let _ = app_handle.emit("import-failed", e.to_string()); } } }); Ok("importing".to_string()) }
async fn do_import_cf_zip(client: &reqwest::Client, paths: &LauncherPaths, zip_path: &str, app: &AppHandle) -> Result<String, String> { let (manifest, data) = launcher_core::modpack::curseforge::read_cf_zip(std::path::Path::new(zip_path)).await.map_err(|e| e.to_string())?; let loader = if manifest.minecraft.mod_loaders.iter().any(|l| l.id.contains("fabric")) { launcher_core::instance::LoaderInfo::Fabric { loader_version: "0.16.0".into() } } else { launcher_core::instance::LoaderInfo::Vanilla }; let spec = launcher_core::instance::NewInstanceSpec { name: manifest.name, minecraft_version: manifest.minecraft.version, loader, memory_mb: 4096 }; let instance_id = launcher_core::instance::create_instance(paths, &spec).await.map_err(|e| e.to_string())?; let minecraft_dir = launcher_core::instance::instance_dir(paths, &instance_id).join(".minecraft"); let mods_dir = minecraft_dir.join("mods"); tokio::fs::create_dir_all(&mods_dir).await.map_err(|e| e.to_string())?; let total = manifest.files.len(); for (i, file) in manifest.files.iter().enumerate() { let dl_url = launcher_core::curseforge::get_download_url(client, file.project_id, file.file_id).await.map_err(|e| e.to_string())?; let cf_files = launcher_core::curseforge::get_files(client, file.project_id).await.map_err(|e| e.to_string())?; let cf_file = cf_files.iter().find(|f| f.id == file.file_id).ok_or_else(|| "file not found".to_string())?; let dest = mods_dir.join(&cf_file.file_name); let downloader = launcher_core::download::Downloader::new(client.clone()); downloader.download(&dl_url, &dest, cf_file.hashes.first().map(|h| h.value.as_str())).await.map_err(|e| e.to_string())?; let _ = app.emit("import-progress", serde_json::json!({"phase": "downloading", "current": i + 1, "total": total})); } let _ = app.emit("import-progress", serde_json::json!({"phase": "overrides"})); launcher_core::modpack::mrpack::extract_overrides(&data, &minecraft_dir, "overrides/").await.map_err(|e| e.to_string())?; let mut detail = launcher_core::instance::get_instance(paths, &instance_id).await.map_err(|e| e.to_string())?; let mut installed = Vec::new(); for file in &manifest.files { installed.push(launcher_core::instance::InstalledMod { filename: format!("cf-{}-{}", file.project_id, file.file_id), source: launcher_core::instance::ModSource::CurseForge { project_id: file.project_id.to_string(), file_id: file.file_id.to_string() }, mod_id: Some(file.project_id.to_string()), name: None, description: None, icon_url: None, version: None, sha1: None, disabled: false }); } detail.mods = installed; detail.summary.mod_count = detail.mods.len() as u32; let json_path = launcher_core::instance::instance_json(paths, &instance_id); let json = serde_json::to_string_pretty(&detail).map_err(|e| e.to_string())?; let tmp = json_path.with_extension("json.tmp"); tokio::fs::write(&tmp, &json).await.map_err(|e| e.to_string())?; tokio::fs::rename(&tmp, &json_path).await.map_err(|e| e.to_string())?; Ok(instance_id) }

pub fn create_builder() -> tauri_specta::Builder<tauri::Wry> { tauri_specta::Builder::<tauri::Wry>::new().commands(tauri_specta::collect_commands![ list_versions, list_accounts, begin_msa_login, launch_vanilla, list_fabric_loaders, search_mods, get_mod_project, get_mod_versions, install_mod, toggle_mod, delete_mod, list_instances, get_instance, create_instance, delete_instance, update_instance, launch_instance, quit_app, preview_mrpack, import_mrpack, get_java_version, search_cf_mods, get_cf_files, install_cf_mod, import_cf_zip ]) }
#[cfg_attr(mobile, tauri::mobile_entry_point)] pub fn run() { tracing_subscriber::fmt().with_env_filter("info,launcher_core=debug,kidomc=debug").init(); let builder = create_builder(); tauri::Builder::default().plugin(tauri_plugin_opener::init()).plugin(tauri_plugin_dialog::init()).manage(AppState::new()).invoke_handler(builder.invoke_handler()).setup(move |app| { input::start_gamepad_bridge(app.handle().clone()); builder.mount_events(app); Ok(()) }).run(tauri::generate_context!()).expect("error while running tauri application"); }
